inputs.text:
{# ============================================================
   BUSINESS PORTRAIT SCENE GENERATOR
   random = случайный выбор
   любое другое значение = использовать заданный текст
   ============================================================ #}


{# ============================================================
   1. USER SETTINGS
   Редактируй только этот раздел
   ============================================================ #}

{% set gender_setting = "man" %}
{% set age_setting = "random" %}
{% set appearance_setting = "random" %}
{% set hair_setting = "completely bald head, clean-shaven scalp, realistic healthy scalp" %}
{% set clothing_setting = "random" %}
{% set location_setting = "random" %}
{% set pose_setting = "random" %}
{% set hands_setting = "random" %}
{% set camera_setting = "random" %}
{% set lighting_setting = "random" %}
{% set mood_setting = "random" %}
{% set details_setting = "random" %}


{# ============================================================
   ПРИМЕР ЧАСТИЧНО ФИКСИРОВАННОЙ ГЕНЕРАЦИИ

   {% set gender_setting = "man" %}
   {% set age_setting = "42-year-old" %}
   {% set appearance_setting = "random" %}
   {% set hair_setting = "completely bald head, clean-shaven scalp" %}
   {% set clothing_setting = "a tailored navy business suit with a white shirt" %}
   {% set location_setting = "random" %}
   {% set pose_setting = "standing naturally with a confident posture" %}
   {% set hands_setting = "hands outside the frame" %}
   {% set camera_setting = "random" %}
   {% set lighting_setting = "random" %}
   {% set mood_setting = "calm confident expression" %}
   {% set details_setting = "random" %}
   ============================================================ #}


{# ============================================================
   2. GENDER
   ============================================================ #}

{% set gender_options = [
    "woman",
    "man"
] %}


{# ============================================================
   3. AGE
   ============================================================ #}

{% set female_age_options = [
    "27-year-old",
    "30-year-old",
    "33-year-old",
    "36-year-old",
    "40-year-old",
    "44-year-old",
    "48-year-old",
    "52-year-old",
] %}

{% set male_age_options = [
    "27-year-old",
    "30-year-old",
    "34-year-old",
    "38-year-old",
    "42-year-old",
    "46-year-old",
    "50-year-old",
    "55-year-old"
] %}


{# ============================================================
   4. APPEARANCE
   ============================================================ #}

{% set female_appearance_options = [
    "well-groomed professional appearance, natural facial features, healthy realistic skin, expressive eyes, subtle professional makeup",
    "elegant executive appearance, refined natural facial features, clear eyes, realistic skin texture, discreet makeup",
    "confident corporate appearance, balanced facial features, healthy skin, expressive eyes, natural professional makeup",
    "approachable business appearance, realistic facial structure, clear eyes, natural skin texture, minimal makeup",
    "mature executive appearance, distinguished natural facial features, healthy realistic skin, restrained professional makeup"
] %}

{% set male_appearance_options = [
    "well-groomed professional appearance, natural masculine facial features, healthy realistic skin, expressive eyes",
    "confident executive appearance, strong natural facial structure, clear eyes, realistic skin texture",
    "approachable business appearance, balanced masculine facial features, healthy skin, professional grooming",
    "mature corporate appearance, distinguished facial features, natural skin texture, confident eyes",
    "refined executive appearance, realistic facial structure, healthy skin, restrained professional grooming"
] %}


{# ============================================================
   5. HAIR
   В мужском списке есть лысые варианты
   ============================================================ #}

{% set female_hair_options = [
    "long straight dark brown hair",
    "shoulder-length softly styled brown hair",
    "long naturally wavy black hair",
    "medium-length blonde hair with a professional style",
    "dark hair tied in a neat low ponytail",
    "short elegant professional haircut",
    "shoulder-length auburn hair",
    "naturally curly dark hair"
] %}

{% set male_hair_options = [
    "short dark brown hair",
    "short neatly styled black hair",
    "short blonde hair",
    "short salt-and-pepper hair",
    "neat professional buzz cut",
    "completely bald head, clean-shaven scalp, realistic healthy scalp",
    "shaved head, realistic healthy scalp",
    "bald head with short neatly groomed beard",
    "short receding hairline, naturally styled"
] %}


{# ============================================================
   6. CLOTHING
   ============================================================ #}

{% set female_clothing_options = [
    "an elegant tailored navy pantsuit with a clean white blouse",
    "a charcoal gray business suit with a cream silk blouse",
    "a light beige blazer with tailored dark trousers",
    "a dark blue professional dress with a structured blazer",
    "a white tailored blazer with navy business trousers",
    "a black premium business suit with a light neutral blouse",
    "a muted burgundy blazer with charcoal tailored trousers"
] %}

{% set male_clothing_options = [
    "a tailored navy business suit with a crisp white dress shirt",
    "a charcoal gray suit with a light blue dress shirt",
    "a dark blue blazer with tailored gray trousers and a white shirt",
    "a black tailored suit with a clean white shirt",
    "a medium gray business suit with a pale blue shirt",
    "a premium navy three-piece suit with a white shirt",
    "a smart casual dark blazer with tailored trousers and an open-collar shirt"
] %}


{# ============================================================
   7. LOCATION
   ============================================================ #}

{% set location_options = [
    "a modern executive office with panoramic windows and a clean minimalist interior",
    "a glass-walled corporate meeting room",
    "a premium high-rise office overlooking a city skyline",
    "a professional photography studio with a soft neutral background",
    "a bright contemporary office with restrained corporate decor",
    "a sophisticated private office with a wooden desk and subtle background details",
    "a luxury corporate lobby with modern architecture",
    "a minimalist coworking space with elegant professional furniture",
    "a modern boardroom with a long conference table",
    "a bright office corridor with glass walls and soft background blur"
] %}


{# ============================================================
   8–9. POSE + HANDS
   Эти параметры объединены, чтобы не создавать противоречий
   ============================================================ #}

{% set pose_hand_options = [
    [
        "standing naturally with a relaxed professional posture",
        "arms relaxed naturally, hands outside the frame"
    ],
    [
        "standing confidently beside an executive desk",
        "one hand resting lightly on the desk, the other arm relaxed and partially outside the frame"
    ],
    [
        "standing with a composed executive posture",
        "arms crossed naturally, hands partially concealed, anatomically correct wrists"
    ],
    [
        "sitting upright at an executive desk",
        "forearms resting naturally on the desk, hands relaxed and separated"
    ],
    [
        "standing beside an open laptop",
        "one hand resting near the laptop, the other hand outside the frame"
    ],
    [
        "standing near a panoramic office window",
        "hands loosely clasped at waist level, fingers relaxed"
    ],
    [
        "sitting naturally in a modern office chair",
        "one forearm resting on the chair arm, the other hand outside the frame"
    ],
    [
        "walking confidently through a modern office",
        "arms moving naturally, hands relaxed and partially outside the frame"
    ],
    [
        "standing while holding a thin business folder",
        "folder held naturally with both hands, fingers partially concealed"
    ],
    [
        "standing beside a conference table",
        "both hands resting lightly and separately on the table edge"
    ],
    [
        "standing in a relaxed three-quarter pose",
        "one hand in a trouser pocket, the other arm relaxed"
    ],
    [
        "upper-body portrait with a straight professional posture",
        "hands completely outside the frame"
    ]
] %}


{# ============================================================
   10. CAMERA / COMPOSITION
   ============================================================ #}

{% set camera_options = [
    "waist-up three-quarter portrait, eye-level camera, 85mm portrait lens, shallow depth of field",
    "upper-body corporate portrait, eye-level camera, 85mm lens, softly blurred background",
    "three-quarter body portrait, slightly low camera angle, 70mm lens, natural perspective",
    "medium business portrait, eye-level camera, 50mm lens, balanced depth of field",
    "chest-up executive portrait, eye-level framing, 85mm lens, soft background bokeh",
    "full-height corporate portrait, eye-level camera, 50mm lens, realistic body proportions",
    "slightly off-center editorial composition, eye-level camera, 85mm lens"
] %}


{# ============================================================
   11. LIGHTING
   ============================================================ #}

{% set lighting_options = [
    "soft natural window light, diffused professional illumination, gentle facial shadows",
    "professional studio lighting with a large softbox and subtle rim light",
    "bright high-key corporate lighting with natural skin tones",
    "soft cinematic office lighting with controlled contrast",
    "warm diffused daylight balanced with subtle interior lighting",
    "clean neutral studio lighting with soft shadows",
    "soft side lighting from panoramic windows with balanced fill light"
] %}


{# ============================================================
   12. MOOD / EXPRESSION
   ============================================================ #}

{% set mood_options = [
    "calm confident expression, slight professional smile, approachable and competent",
    "serious executive expression, composed and authoritative",
    "friendly professional smile, warm and trustworthy",
    "neutral focused expression, intelligent and self-assured",
    "subtle confident smile, polished and successful",
    "calm thoughtful expression, attentive and professional",
    "relaxed executive expression, confident but approachable"
] %}


{# ============================================================
   13. ADDITIONAL DETAILS
   ============================================================ #}

{% set details_options = [
    "realistic premium fabric texture, detailed natural hair, clean background, restrained corporate color grading",
    "premium tailoring, realistic material details, natural skin texture, polished editorial finish",
    "clean luxury corporate aesthetics, realistic individual hair strands, subtle professional color grading",
    "authentic office atmosphere, detailed clothing texture, balanced highlights and shadows",
    "subtle elegant accessories, realistic fabric folds, clean professional background",
    "high-end editorial styling, accurate clothing seams, natural skin tones, realistic photographic finish"
] %}


{# ============================================================
   14. RESOLVE GENDER
   ============================================================ #}

{% if gender_setting == "random" %}
    {% set gender = gender_options | random %}
{% else %}
    {% set gender = gender_setting %}
{% endif %}


{# ============================================================
   15. SUBJECT DESCRIPTION
   ============================================================ #}

{% if gender == "woman" %}
    {% set subject = "successful businesswoman, senior corporate executive" %}
{% else %}
    {% set subject = "successful businessman, senior corporate executive" %}
{% endif %}


{# ============================================================
   16. RESOLVE AGE
   ============================================================ #}

{% if age_setting == "random" %}
    {% if gender == "woman" %}
        {% set age = female_age_options | random %}
    {% else %}
        {% set age = male_age_options | random %}
    {% endif %}
{% else %}
    {% set age = age_setting %}
{% endif %}


{# ============================================================
   17. RESOLVE APPEARANCE
   ============================================================ #}

{% if appearance_setting == "random" %}
    {% if gender == "woman" %}
        {% set appearance = female_appearance_options | random %}
    {% else %}
        {% set appearance = male_appearance_options | random %}
    {% endif %}
{% else %}
    {% set appearance = appearance_setting %}
{% endif %}


{# ============================================================
   18. RESOLVE HAIR
   ============================================================ #}

{% if hair_setting == "random" %}
    {% if gender == "woman" %}
        {% set hair = female_hair_options | random %}
    {% else %}
        {% set hair = male_hair_options | random %}
    {% endif %}
{% else %}
    {% set hair = hair_setting %}
{% endif %}


{# ============================================================
   19. RESOLVE CLOTHING
   ============================================================ #}

{% if clothing_setting == "random" %}
    {% if gender == "woman" %}
        {% set clothing = female_clothing_options | random %}
    {% else %}
        {% set clothing = male_clothing_options | random %}
    {% endif %}
{% else %}
    {% set clothing = clothing_setting %}
{% endif %}


{# ============================================================
   20. RESOLVE LOCATION
   ============================================================ #}

{% if location_setting == "random" %}
    {% set location = location_options | random %}
{% else %}
    {% set location = location_setting %}
{% endif %}


{# ============================================================
   21. RESOLVE POSE AND HANDS

   Если pose_setting = random:
   поза и руки выбираются согласованной парой.

   Если pose_setting фиксирован:
   используется pose_setting, а hands_setting задаётся отдельно.
   ============================================================ #}

{% if pose_setting == "random" %}
    {% set pose_hand = pose_hand_options | random %}
    {% set pose = pose_hand[0] %}
    {% set hands = pose_hand[1] %}
{% else %}
    {% set pose = pose_setting %}

    {% if hands_setting == "random" %}
        {% set hands = "hands naturally positioned, relaxed fingers, anatomically correct wrists" %}
    {% else %}
        {% set hands = hands_setting %}
    {% endif %}
{% endif %}


{# ============================================================
   22. RESOLVE CAMERA
   ============================================================ #}

{% if camera_setting == "random" %}
    {% set camera = camera_options | random %}
{% else %}
    {% set camera = camera_setting %}
{% endif %}


{# ============================================================
   23. RESOLVE LIGHTING
   ============================================================ #}

{% if lighting_setting == "random" %}
    {% set lighting = lighting_options | random %}
{% else %}
    {% set lighting = lighting_setting %}
{% endif %}


{# ============================================================
   24. RESOLVE MOOD
   ============================================================ #}

{% if mood_setting == "random" %}
    {% set mood = mood_options | random %}
{% else %}
    {% set mood = mood_setting %}
{% endif %}


{# ============================================================
   25. RESOLVE DETAILS
   ============================================================ #}

{% if details_setting == "random" %}
    {% set details = details_options | random %}
{% else %}
    {% set details = details_setting %}
{% endif %}


{# ============================================================
   26. FINAL POSITIVE PROMPT
   ============================================================ #}

professional business portrait of a {{ age }} {{ gender }},
{{ subject }},
{{ appearance }},
{{ hair }},
wearing {{ clothing }},
{{ pose }},
{{ hands }},
inside {{ location }},
{{ camera }},
{{ lighting }},
{{ mood }},
{{ details }},
high-end corporate photography,
photorealistic,
realistic natural skin texture,
sharp expressive eyes,
natural body proportions,
realistic human anatomy,
professional composition,
high dynamic range,
balanced natural colors,
sharp focus,
premium editorial quality
